        "$$\\eqalign{\n  &amp; P\\,\\,\\,\\,Q\\,\\,\\,\\,R\\,\\,\\,\\,S  \\cr \n  &amp; 3\\,\\,\\,\\,\\,\\,2\\,\\,\\,\\,\\,1\\,\\,\\,\\,\\,4 \\cr} $$",
        "$$\\eqalign{\n  &amp; P\\,\\,\\,\\,Q\\,\\,\\,\\,R\\,\\,\\,\\,S  \\cr \n  &amp; 4\\,\\,\\,\\,\\,\\,2\\,\\,\\,\\,\\,1\\,\\,\\,\\,\\,3 \\cr} $$",
        "$$\\eqalign{\n  &amp; P\\,\\,\\,\\,Q\\,\\,\\,\\,R\\,\\,\\,\\,S  \\cr \n  &amp; 4\\,\\,\\,\\,\\,\\,1\\,\\,\\,\\,\\,2\\,\\,\\,\\,\\,3 \\cr} $$"
